int sum = 0;
for (int i = 1; i <= 4; i++) {
    if (i % 2 == 0) continue;
    sum += i;
}
IO.println(sum);

int count = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 4; j++) {
        count++;
    }
}
IO.println(count);
